/**
 * Source catalog (Stage 09): official data sources with their licences, keys, rate
 * limits, data dictionaries and revision rules, plus the risk register, the company
 * candidates and the acquisition plan. Metadata only; no data.
 *
 * The JSON is generated by `python -m multiverse_contracts.source_catalog` from the
 * Python contracts, which also validate it, so the cast below is safe. It is the payload
 * of the future `GET /api/v1/sources`.
 */
import type { SourceCatalog } from "./generated/contracts";
import data from "../../catalog/sources.json";

export type DataSource = SourceCatalog["sources"][number];
export type SourceDataset = DataSource["datasets"][number];
export type Risk = SourceCatalog["risks"][number];
export type CompanyCandidate = SourceCatalog["candidates"][number];

// JSON imports widen literal types; the Python contracts validate the file in CI.
export const SOURCE_CATALOG: SourceCatalog = data as unknown as SourceCatalog;
